import React from 'react';

export default function SimplifySection({ originalText, simplifiedText, setSimplifiedText }) {
  // Placeholder: implement API call to backend for simplification
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
      <div>
        <h2 className="font-bold mb-2">Original Text</h2>
        <textarea className="w-full h-48 p-2 border rounded" value={originalText} readOnly />
      </div>
      <div>
        <h2 className="font-bold mb-2">Simplified Text</h2>
        <textarea className="w-full h-48 p-2 border rounded" value={simplifiedText} readOnly />
        <div className="text-sm text-gray-500 mt-2">(Simplified text will appear here)</div>
      </div>
    </div>
  );
}
